import abc

import six

from ute_common_abstract_core import logger
from ute_common_abstract_core.device_pool import DeviceActivePools, CfgFileBasedDevicePool, check_device_capabilities
from ute_common_abstract_core.exceptions import RequiredDeviceNotFound, UnknownDevice, PoolCreationError
from .exceptions import RequiredUeNotFound, UnknownUe, UnknownUeGroup, UnknownUePoolPackage
from .exceptions import NotEnoughRequiredUes
from .utils.decorators import exception_reraise_decorator

STARTING_CELL = "STARTING_CELL"


def check_ue_location(ue_config, req_starting_cell):
    """
    Check whether given ue config has required location.

    :param ue_config: UE Configuration
    :param req_starting_cell: Required starting cell. if value is None function returns True
    :return: Boolean. True if UE is in required cell, otherwise False
    """
    ue_starting_cell = get_starting_cell(ue_config)
    logger.debug(f'UE starting_cell: {ue_starting_cell}, {type(ue_starting_cell)}')
    return True if (req_starting_cell is None) or (req_starting_cell == ue_starting_cell) else False


def get_starting_cell(configuration):
    """
    Get starting cell from ue configuration dictionary.

    :param configuration: UE configuration
    :return: configured starting cell. If not defined in configuration None is returned
    """
    if STARTING_CELL in configuration:
        return configuration[STARTING_CELL]
    else:
        return None


@six.add_metaclass(abc.ABCMeta)
class LteUePool:
    """
    Specific pools don't need to be derived classed. They may differ in constructor signature.

    Expected behaviour is to have get_ue() method that either finds UE fulfilling specified
    requirements or raises informative exception.

    Pool should track issued UEs to not issue UE-in-use.
    UE must come back to pool via release_ue() before it can be issued once more via get_ue().
    """

    DEVICE_TYPES = "UE_TYPES"

    def __init__(self):  # allowed constructor with any signature
        """Basic initialization."""
        pass

    @abc.abstractmethod
    def get_ue(self, ue_characteristics):
        """
        Return LteUe instance fulfilling requirements. (public API)

        :return: ue instance
        :raises: :py:class:`ute_ue.exceptions.RequiredUeNotFound`: If matching ue is not found
        """
        pass

    @abc.abstractmethod
    def release_ue(self, ue):
        """
        Allow UE to be reused - it should be in pool of available UEs. (public API)

        :raises: :py:class:`ute_ue.exceptions.UnknownUe`: If given ue has not been returned from this pool via get_ue()
        :return: None
        """
        ue.reserved = False

    # we don't use @abc.abstractmethod here to not force all plugins to implement it
    # ue-groups are mainly for simulator-based-UEs
    def get_ue_group(self, ue_characteristics, ues_number):
        """
        Return UE-group instance fulfilling requirements. (public API)

        :param ue_characteristics: requirements for UE
        :param ues_number: needed number of UEs with such requirements
        :return: ue group instance
        :raises: :py:class:`ute_ue.exceptions.NotEnoughRequiredUes`: If not enough matching ues found
        """
        raise NotImplementedError()

    def release_ue_group(self, ue_group):
        """
        Release UEs contained in UE-group into uepool. (public API)

        :param ue_group: UE-group instance
        :return: None
        """
        raise NotImplementedError()


class UeActivePools(DeviceActivePools, LteUePool):
    """Container of all LteUePools active on given Testline."""

    DEVICE_POOL_TYPE = "UE_POOLS"

    def __init__(self):
        """Basic initialization."""
        super().__init__(self.DEVICE_POOL_TYPE)

    def convert_pool_type_2_pool_class_fullname(self, ue_pool_type):
        """
        Encapsulate convention how to produce full package.module.class name for given UePool type.

        :param ue_pool_type: UePool type
        :return: full package.module.class name
        """
        class_name = ue_pool_type                                                           # IphyUePool
        module_name = class_name.lower()                                                    # iphyuepool
        (ue_type_name, ue_str, rest) = module_name.partition("ue")                          # (iphy, ue, pool)
        if ue_str and rest:
            package_name = f"ute_ue.ue.{ue_type_name}"                               # ute_ue.ue.iphy
            pool_class_fullname = f"{package_name}.{module_name}.{class_name}"  # ute_ue.ue.iphy.iphyuepool.IphyUePool
            return pool_class_fullname
        else:
            raise UnknownUePoolPackage(module_name, class_name)

    @exception_reraise_decorator(RequiredDeviceNotFound, RequiredUeNotFound)
    def get_ue(self, ue_characteristics):
        """
        Return LteUe instance fulfilling requirements.

        :param ue_characteristics: description of what is required from ue
        :return: ue instance, that matches given search criteria
        :raises: :py:class:`ute_ue.exceptions.RequiredUeNotFound`: If matching ue is not found
        :raises: :py:class:`ute_common_abstract_core.exceptions.ConfigurationNotDefined`: If UE configuration cannot be found
        """
        return self._get_device(ue_characteristics)

    @exception_reraise_decorator(UnknownDevice, UnknownUe)
    def release_ue(self, ue):
        """
        Allow UE to be reused - it should be in pool of available UEs.

        :param ue:
        :return: None
        """
        ue.reserved = False
        self._release_device(ue)

    def get_ue_group(self, ue_characteristics, ues_number):
        """
        Return UE-group instance fulfilling requirements.

        :param ue_characteristics: requirements for UE
        :param ues_number: needed number of UEs with such requirements
        :return: ue group instance
        :raises: :py:class:`ute_ue.exceptions.NotEnoughRequiredUes`: If not enough matching ues found
        """
        if not self._active_pools:
            self.logger.error(f"{self}: has no active pool")
            err_log = self._get_failed_pool_creation_msg()
            raise PoolCreationError(f'None of {self.device_pool_type} has been created.\n{err_log}')

        for (idx, ue_pool) in enumerate(self._active_pools):
            self.logger.debug('UeActivePools: current pool in search:' + str(ue_pool.__class__.__name__))
            try:
                ue_group = ue_pool.get_ue_group(ue_characteristics=ue_characteristics, ues_number=ues_number)
                self._remember_device_creating_pool(ue_group, ue_pool)
                msg = f"{self}: {ue_group} taken from   {ue_pool}"
                self.logger.debug(msg)
                return ue_group
            except (NotEnoughRequiredUes, NotImplementedError) as exc:
                if (idx + 1) == len(self._active_pools):
                    self.logger.error(f"{self}: {exc!r}")
                    raise  # it is 'not found' inside last pool
                else:
                    self.logger.debug(f"{self}: {exc!r}")

    def release_ue_group(self, ue_group):
        """
        Release UEs contained in UE-group into uepool.

        :param ue_group: UE-group instance
        :return: None
        :raises: :py:class:`ute_ue.exceptions.UnknownUeGroup`: If given ue-group has not been returned via get_ue_group()
        """
        if id(ue_group) in self._pool_that_created_device:
            # TODO: pop as fix in ute_common_abstract_core/device_pool.py _release_device()
            uegroup_creating_pool = self._pool_that_created_device.pop(id(ue_group))
            self.logger.debug(f"{self}: {ue_group} returning to {uegroup_creating_pool}")
            uegroup_creating_pool.release_ue_group(ue_group=ue_group)
        else:
            cause_1 = 'has not been withdrawn from ue-pool'
            cause_2 = 'has been already released to ue-pool'
            exc = UnknownUeGroup(f"{ue_group} {cause_1} or it {cause_2}")
            self.logger.error(f"{self}: {exc!r}")
            raise exc


class CfgFileBasedUePool(CfgFileBasedDevicePool, LteUePool):
    """Configuration File Based Ue Pool"""

    @exception_reraise_decorator(RequiredDeviceNotFound, RequiredUeNotFound)
    def get_ue(self, ue_characteristics):
        """
        Return LteUe instance fulfilling requirements.

        :param ue_characteristics: description of what is required from ue
        :return: ue instance, that matches given search criteria
        :raises: :py:class:`ute_ue.exceptions.RequiredUeNotFound`: If matching ue is not found
        """
        return self._get_device(ue_characteristics)

    @exception_reraise_decorator(UnknownDevice, UnknownUe)
    def release_ue(self, ue):
        """
        Allow UE to be reused - it should be in pool of available UEs.

        :return: None
        :raises: :py:class:`ute_ue.exceptions.UnknownUe`: If given ue has not been returned from this pool via get_ue()
        """
        ue.reserved = False
        self._release_device(ue)

    def _has_matching_characteristics(self, ue_config, ue_characteristics):
        capabilities = ue_characteristics.domain_capabilities
        starting_cell = ue_characteristics.starting_cell
        if check_device_capabilities(ue_config, capabilities) and \
           check_ue_location(ue_config, starting_cell):
            return True
        return False
